using System.Collections.Generic;
using UnityEngine;
using StickMate.Core;

namespace StickMate.Interaction
{
    internal static partial class AccessoryShapeBuilder
    {
        /// <summary>이 자리의 좌표를 <b>인계본 조각 표</b>(이 파일)가 갖는가. NECK 4종은 에셋이 갖는다(여기서는 false).</summary>
        internal static bool IsHandoffCode(EquipmentSlot slot, int item)
        {
            switch (slot)
            {
                case EquipmentSlot.Head:
                    return item == HeadCap || item == HeadBeanie || item == HeadFedora || item == HeadCrown;
                case EquipmentSlot.Eyes:
                    return item == EyesSunglasses || item == EyesRound || item == EyesGoggles || item == EyesMonocle;
                case EquipmentSlot.Shoulders:
                    return item == BackCape || item == BackLongCape || item == BackWings || item == BackBackpack;
                default:
                    return false;
            }
        }

        /// <summary>코드 자리의 아이템 단위 몸 표면 파라미터(그룹 알파 · 배율 u/u_card · 세로 압축 ky · 세로 오프셋 · 반전). 에셋 자리는 ItemCatalog.WornTransform.</summary>
        internal static AccessoryWornTransform WornTransformCode(EquipmentSlot slot, int item)
        {
            switch (slot)
            {
                case EquipmentSlot.Head:
                    switch (item)
                    {
                        case HeadCap: return new AccessoryWornTransform(0f, 0f, 0f, 0f, false);   // clothhat
                        case HeadBeanie: return new AccessoryWornTransform(0f, 1.5977f, 0.676f, 0.13521f, false);   // furhat
                        case HeadFedora: return new AccessoryWornTransform(0f, 0f, 0f, 0f, false);   // fedora
                        case HeadCrown: return new AccessoryWornTransform(0f, 0f, 0f, 0f, false);   // crown
                        default: return AccessoryWornTransform.None;
                    }
                case EquipmentSlot.Eyes:
                    switch (item)
                    {
                        case EyesSunglasses: return new AccessoryWornTransform(0f, 0f, 0f, 0f, false);   // sunglasses
                        case EyesRound: return new AccessoryWornTransform(0f, 0f, 0f, 0f, false);   // roundglasses
                        case EyesGoggles: return new AccessoryWornTransform(0f, 0f, 0f, 0f, false);   // goggles
                        case EyesMonocle: return new AccessoryWornTransform(0f, 0f, 0f, 0f, false);   // monocle
                        default: return AccessoryWornTransform.None;
                    }
                case EquipmentSlot.Shoulders:
                    switch (item)
                    {
                        case BackCape: return new AccessoryWornTransform(0f, 0f, 0f, 0f, false);   // shortcape
                        case BackLongCape: return new AccessoryWornTransform(0f, 0f, 0f, 0f, false);   // longcape
                        case BackWings: return new AccessoryWornTransform(0f, 0f, 0f, 0f, false);   // wings
                        case BackBackpack: return new AccessoryWornTransform(0f, 0f, 0f, 0f, false);   // backpack
                        default: return AccessoryWornTransform.None;
                    }
                default:
                    return AccessoryWornTransform.None;
            }
        }

        /// <summary>인계본 조각을 <paramref name="sink"/>에 더한다. 이 자리를 이 표가 갖지 않으면 false(옛 switch 로).</summary>
        private static bool AppendHandoff(List<Shape> sink, EquipmentSlot slot, int item, in Rig rig, AccessorySurface surface)
        {
            if (!IsHandoffCode(slot, item)) return false;
            AccessoryWornTransform xf = surface == AccessorySurface.Body ? WornTransformCode(slot, item) : AccessoryWornTransform.None;
            switch (slot)
            {
                case EquipmentSlot.Head: return AppendHandoffHead(sink, item, rig, xf);
                case EquipmentSlot.Eyes: return AppendHandoffEyes(sink, item, rig, xf);
                case EquipmentSlot.Shoulders: return AppendHandoffShoulders(sink, item, rig, xf);
                default: return false;
            }
        }

